//! PRD-mcphost-python-sdk-generated AC2 (P0) -- Given the generated package,
//! When `uv run mypy --strict mcphost_sdk` and `uv run pytest` run, Then both
//! exit 0 and every file under `mcphost_sdk/` carries the generated-from
//! header with the contract's `1.<sha12>`.


use crate::pysdk;

#[test]
fn pysdk_ac02_mypy_strict_and_pytest_pass_and_every_file_has_the_header() {
    let sha = mcphost::api_contract::sha_hex(mcphost::call_cli::EMBEDDED_CONTRACT);
    let header = format!(
        "# generated by mcphost gen sdk python from contract 1.{} -- do not edit",
        &sha[..12]
    );
    let files = pysdk::package_files(&pysdk::sdk_dir().join("mcphost_sdk"));
    assert!(files.len() >= 7, "expected the full package, got {files:?}");
    for f in &files {
        let first = std::fs::read_to_string(f).unwrap().lines().next().unwrap_or_default().to_string();
        assert_eq!(first, header, "{} lacks the generated-from header", f.display());
    }

    let mypy = pysdk::uv(&["run", "mypy", "--strict", "mcphost_sdk"]);
    assert!(mypy.status.success(), "mypy --strict failed:\n{}", pysdk::text(&mypy));
    let pytest = pysdk::uv(&["run", "pytest", "-q"]);
    assert!(pytest.status.success(), "pytest failed:\n{}", pysdk::text(&pytest));
}
